CREATE TABLE eng.w_hedge (hedge_rel_id INT NOT NULL, slope DECIMAL(12,4) NULL, r2 DECIMAL(12,4) NULL, prospective BIT NULL, base_item DECIMAL(19,2) NULL, base_instr DECIMAL(19,2) NULL, closeout DATE NULL, floor_amt DECIMAL(19,2) NULL, oci_bal DECIMAL(19,2) NULL, cum_item_prev DECIMAL(19,2) NULL, cum_instr_prev DECIMAL(19,2) NULL, price_date DATE NULL);
CREATE TABLE eng.w_hedge_m (hedge_rel_id INT NOT NULL, ci DECIMAL(19,2) NOT NULL, cin DECIMAL(19,2) NOT NULL, assessed BIT NULL, ratio DECIMAL(12,4) NULL, effective BIT NULL, eff_cum DECIMAL(19,2) NULL, oci_add DECIMAL(19,2) NULL, d_instr DECIMAL(19,2) NULL);
